import{_ as o,o as a,c as t,ak as r}from"./chunks/framework.B8jO0odJ.js";const g=JSON.parse('{"title":"Chainy gameplay storyboard set","description":"Historical concept art, superseded November 11, 2026.\\nThe economy, restoration, and conditional-classifier sequences below do not govern the current game.\\nUse the lesson-colle","frontmatter":{"title":"Chainy gameplay storyboard set","description":"Historical concept art, superseded November 11, 2026.\\nThe economy, restoration, and conditional-classifier sequences below do not govern the current game.\\nUse the lesson-colle","source":"docs/media/gdd/storyboards/README.md","category":"Other documents","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/media/gdd/storyboards/readme.md","filePath":"content/docs/media/gdd/storyboards/readme.md"}'),d={name:"content/docs/media/gdd/storyboards/readme.md"};function c(n,e,i,s,l,h){return a(),t("div",null,[...e[0]||(e[0]=[r('<div><h1 id="chainy-gameplay-storyboard-set">Chainy gameplay storyboard set<a class="header-anchor" href="#chainy-gameplay-storyboard-set" aria-label="Link to this section">​</a></h1><blockquote><p><strong>Historical concept art, superseded November 11, 2026.</strong> The economy, restoration, and conditional-classifier sequences below do not govern the current game. Use the <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">lesson-collection GDD</a> for current gameplay; retain these sheets only as visual and provenance references.</p></blockquote><p>Generated October 26, 2026 with the built-in image-generation tool and the approved Chainy visual references. All seven PNGs are 1920 x 1080, opaque, landscape storyboard sheets with eight numbered panels.</p><p>These images are GDD and production-handoff concepts. They are not Android screenshots, implementation evidence, editable Unity UI, production-ready meshes, or proof that the depicted systems have passed device testing. Rebuild interfaces as native editable UI and validate safe areas, touch targets, text scaling, accessibility, save behavior, and performance on named Android devices.</p><h2 id="deliverables">Deliverables<a class="header-anchor" href="#deliverables" aria-label="Link to this section">​</a></h2><table><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>how-game-works.png</code></td><td>Overall offline profile, world, objective, interaction, restoration, and checkpoint loop</td></tr><tr><td><code>how-to-navigate.png</code></td><td>Fixed-isometric movement, landmarks, nearby interaction, modal input locking, journals, and pause</td></tr><tr><td><code>how-to-play-web3-world.png</code></td><td>W01-W04 fictional wallet, one-time reward, Lantern #014 purchase, ownership, and workshop restoration</td></tr><tr><td><code>how-to-play-blockchain-world.png</code></td><td>B01-B03 and demo B07 trusted-record inspection, linked-block repair, altered/stale distinction, and beacon restoration</td></tr><tr><td><code>how-to-play-ai-world.png</code></td><td>Clearly labelled proposed stretch chapter for examples, local classification, separate testing, limitations, and human review</td></tr><tr><td><code>how-settings-work.png</code></td><td>Supported audio, mute, silent feedback, dialogue pacing, apply/back, and saved-resume behavior</td></tr><tr><td><code>how-game-mechanics-work.png</code></td><td>Quest-state, interaction, retry, atomic-save, restoration, and learning-record grammar</td></tr></tbody></table><h2 id="common-generation-specification">Common generation specification<a class="header-anchor" href="#common-generation-specification" aria-label="Link to this section">​</a></h2><ul><li>Use case: illustration-story / high-fidelity game UI storyboard.</li><li>Asset type: one 16:9 instructional storyboard sheet, not eight separate images.</li><li>References: <code>current-visuals/isometric-exploration.png</code>, <code>current-visuals/dialogue-overlay.png</code>, <code>reference-chainy-01.png</code>, <code>reference-chainy-02.png</code>, plus the relevant <code>gameplay-first</code> concept sheet.</li><li>Layout: exact 1920 x 1080; four equal panels per row; eight numbered panels; large short English headings; generous gutters and safe margins.</li><li>Visual language: fixed orthographic isometric camera around 40 degrees downward; restrained faceted low-poly stone islands; olive grass; blue water; small blue-haired, yellow-clad Explorer; reusable white screen-faced robot guides with cyan expressions; dark navy UI with restrained cyan outlines.</li><li>Constraints: offline and fictional systems only; no real wallet, cryptocurrency, public blockchain, learner data, secrets, cloud AI, combat, free-camera control, logos, watermarks, voxel terrain, glossy toy rendering, or copied third-party maps and HUDs.</li></ul><h2 id="final-prompt-sequences">Final prompt sequences<a class="header-anchor" href="#final-prompt-sequences" aria-label="Link to this section">​</a></h2><h3 id="how-the-game-works">How the game works<a class="header-anchor" href="#how-the-game-works" aria-label="Link to this section">​</a></h3><p><code>SELECT DEMO PROFILE</code> -&gt; <code>CHOOSE A WORLD</code> -&gt; <code>CHECK THE OBJECTIVE</code> -&gt; <code>EXPLORE THE ROUTE</code> -&gt; <code>TALK TO THE GUIDE</code> -&gt; <code>COMPLETE THE ACTION</code> -&gt; <code>SEE THE WORLD RESTORED</code> -&gt; <code>SAVE AND CONTINUE</code>. Web3 is open first; later worlds show prerequisites. Dialogue suspends movement. Completion uses <code>INTRO CHAPTER COMPLETE</code>, not a claim of full-world completion.</p><h3 id="how-to-navigate">How to navigate<a class="header-anchor" href="#how-to-navigate" aria-label="Link to this section">​</a></h3><p><code>FIXED ISOMETRIC VIEW</code> -&gt; <code>MOVE WITH JOYSTICK</code> -&gt; <code>FOLLOW LANDMARKS</code> -&gt; <code>INTERACT WHEN NEAR</code> -&gt; <code>WORLD INPUT PAUSED</code> -&gt; <code>OPEN QUEST LOG</code> -&gt; <code>OPEN ENCYCLOPEDIA</code> -&gt; <code>BACK OR PAUSE</code>. No jumping, combat, camera rotation, or precision platforming.</p><h3 id="how-to-play-web3-world">How to play Web3 World<a class="header-anchor" href="#how-to-play-web3-world" aria-label="Link to this section">​</a></h3><p><code>MEET SEAN</code> -&gt; <code>HELP A RESIDENT</code> -&gt; <code>EARN 12 COINS</code> -&gt; <code>INSPECT LANTERN #014</code> -&gt; <code>REVIEW THE COST</code> -&gt; <code>WAIT FOR CONFIRMATION</code> -&gt; <code>CHECK OWNERSHIP</code> -&gt; <code>RESTORE THE WORKSHOP</code>. The review shows price 8 + fee 1 = total 9, remaining 3, and Authorize/Cancel. The 12-coin balance first appears after the one-time reward. Pending does not claim ownership; equipping is free; successful restoration is saved.</p><h3 id="how-to-play-blockchain-world">How to play Blockchain World<a class="header-anchor" href="#how-to-play-blockchain-world" aria-label="Link to this section">​</a></h3><p><code>MEET MATTHEW</code> -&gt; <code>READ THE VERIFIED RECORD</code> -&gt; <code>START AT CHECKPOINT A</code> -&gt; <code>INSPECT THREE BLOCKS</code> -&gt; <code>LINK THE SEQUENCE</code> -&gt; <code>REJECT THE ALTERED COPY</code> -&gt; <code>CHECK THE COPY</code> -&gt; <code>RESTORE THE BEACON</code>. Trusted A is followed by three subsequent blocks. The altered local copy says 6 while verified evidence says 8; a stale copy is separately labelled as missing the latest block. The player repairs a local display from trusted evidence and does not rewrite global history or create consensus.</p><h3 id="how-to-play-ai-world">How to play AI World<a class="header-anchor" href="#how-to-play-ai-world" aria-label="Link to this section">​</a></h3><p>Title includes <code>PROPOSED STRETCH CHAPTER</code>. <code>MEET LEE</code> -&gt; <code>CHECK EVIDENCE</code> -&gt; <code>LABEL EXAMPLES</code> -&gt; <code>TEACH BOT</code> -&gt; <code>TEST NEW CASES</code> -&gt; <code>LEARN FROM A MISTAKE</code> -&gt; <code>FRESH FINAL SET</code> -&gt; <code>HUMAN REVIEW</code>. The local classifier is represented by example cards and a small terminal, not a brain, cloud, or blockchain cube. Training, practice, and reserved final cases remain separate. Predictions can be wrong; no confidence percentage or guaranteed fraud detection is shown; a person approves any fictional action.</p><h3 id="how-settings-work">How settings work<a class="header-anchor" href="#how-settings-work" aria-label="Link to this section">​</a></h3><p><code>OPEN SETTINGS</code> -&gt; <code>MUSIC VOLUME</code> -&gt; <code>SOUND FX VOLUME</code> -&gt; <code>SILENT PLAY</code> -&gt; <code>FEEDBACK STAYS CLEAR</code> -&gt; <code>CONTROL DIALOGUE PACE</code> -&gt; <code>APPLY OR GO BACK</code> -&gt; <code>RESUME SAVED GAME</code>. The concept does not add graphics quality, language switching, online accounts, or cloud synchronization.</p><h3 id="how-game-mechanics-work">How game mechanics work<a class="header-anchor" href="#how-game-mechanics-work" aria-label="Link to this section">​</a></h3><p><code>LOCKED</code> -&gt; <code>AVAILABLE -&gt; ACTIVE</code> -&gt; <code>EXPLORE &amp; INSPECT</code> -&gt; <code>DIALOGUE &amp; CHOICE</code> -&gt; <code>INSPECT -&gt; DECIDE -&gt; CONFIRM</code> -&gt; <code>EXPLAIN &amp; RETRY</code> -&gt; <code>ATOMIC LOCAL SAVE</code> -&gt; <code>RESTORE &amp; CONTINUE</code>. Early pickups remain collected, one-time rewards do not repeat, only one interaction layer owns input, and quest/balance/inventory/ledger/world changes save together or not at all. The encyclopedia uses Discovered, Explained, Practiced, and New Situation rather than a mastery percentage.</p><h2 id="handoff">Handoff<a class="header-anchor" href="#handoff" aria-label="Link to this section">​</a></h2><p>Luis owns production art, Miguel owns production UI, Christian owns Unity integration and measured device validation, Sherwin owns player-experience decisions, and Sean owns final authored instructional wording. Retain editable source files and provenance/license notes for any production replacement assets.</p></div>',1)])])}const E=o(d,[["render",c]]);export{g as __pageData,E as default};
